-- pay_waffo_expire_gold_identities()
CREATE OR REPLACE FUNCTION public.pay_waffo_expire_gold_identities()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE n integer;
BEGIN
  DELETE FROM opening_grant_identity_digests WHERE purpose IN ('gold_purchase_test','gold_purchase_live')
    AND expires_at<=now();
  GET DIAGNOSTICS n=ROW_COUNT;
  -- A resolved order no longer needs identity material. Pending late-payment recovery retains it.
